SELECT t.id,t.name,array_agg(DISTINCT p.provider_key ORDER BY p.provider_key) AS open_matchday_keys FROM core.teams t LEFT JOIN core.provider_ids p ON p.entity_id=t.id AND p.entity_type='team' AND p.provider='open_matchday' AND p.is_current WHERE t.id IN (3224,3226,3236,3238,3420,3421,3422,3423,3424,5426,3225,3228,3230,3231,3232,3233,3239,3240,5561,13538,3212,3213,3214,3215,3217,3218,3219,3220,3221,3427) GROUP BY t.id,t.name ORDER BY t.id